43	  if (challenges.length === 0) {
44	    return `No PM challenges yet on "${requirement.title}". Proposed with ${requirement.evidenceLevel} evidence from ${requirement.linkedSourceIds.length} source(s).`;
45	  }
46	  const latest = challenges[challenges.length - 1];
47	  return `PM challenged "${requirement.title}": "${latest.rationale}". The requirement was revised in response — see the audit log for the exact before/after.`;
48	}
49	
