51	  reviews: StakeholderReview[];
52	}
53	
54	/**
55	 * MOCK. Replace with: OpenAI call that reads all reviews for a requirement
56	 * (or workflow) and produces a short synthesis of where reviewers agree,
57	 * disagree, and why — the "AI overview of who says what" from the brief.
58	 */
59	export function summarizeStakeholderReviews(input: StakeholderOverviewInput): string {
