1	// Shared domain types for the BMW PM Decision Workflow app.
2	// This is the contract every role builds against. Changing a shape here
3	// is a team-wide announcement, not a solo edit.
4	
5	export type ComponentKey =
6	  | "exterior"
7	  | "interior"
8	  | "windows"
9	  | "steering"
10	  | "engine"
11	  | "battery";
12	
13	export interface Vehicle {
14	  id: string;
15	  name: string; // e.g. "BMW 5 Series"
16	  generation: string; // e.g. "G60 -> successor"
17	  markets: string[]; // e.g. ["Europe", "China", "United States"]
18	}
19	
20	export interface VehicleComponent {
21	  id: string;
22	  vehicleId: string;
23	  key: ComponentKey;
24	  label: string; // "Battery & Charging"
25	  hotspot: { xPct: number; yPct: number }; // position on the 360 viewer, 0-100
26	  workflowId: string | null; // null => "create new" affordance on landing page
27	}
28	
29	// ---------- Workflow / pipeline ----------
30	
31	export type WorkflowStatus =
32	  | "draft"
33	  | "analyzing"
34	  | "stakeholder_review"
35	  | "pm_review"
36	  | "approved"
37	  | "rejected"
38	  | "archived";
39	
40	export type StageKey =
41	  | "ingest"
42	  | "enrich"
43	  | "extract"
44	  | "derive"
45	  | "score"
46	  | "stakeholder_review"
47	  | "pm_decision"
48	  | "deploy";
49	
50	export type StageStatus = "pending" | "active" | "complete" | "blocked" | "skipped";
51	
52	export interface Stage {
53	  key: StageKey;
54	  label: string;
55	  status: StageStatus;
56	  startedAt: string | null;
57	  completedAt: string | null;
58	  owner: "ai" | "pm" | "stakeholder";
59	}
60	
61	export interface Workflow {
62	  id: string;
63	  vehicleId: string;
64	  componentId: string;
65	  market: string;
66	  status: WorkflowStatus;
67	  stages: Stage[];
68	  createdAt: string;
69	  updatedAt: string;
70	}
71	
72	// ---------- Evidence chain: sources -> signals -> requirements ----------
73	
74	export type DatasetType = "verbatim" | "equipment" | "sales" | "study" | "web";
75	export type ReliabilityTier = "first_party" | "official" | "review_site" | "forum";
76	
77	export interface SourceRecord {
78	  id: string;
79	  workflowId: string;
80	  datasetType: DatasetType;
81	  reliability: ReliabilityTier;
82	  title: string;
83	  excerpt: string;
84	  url: string | null; // null for internal datasets
85	  retrievedAt: string;
86	  // Optional metadata, populated when a source is derived from real
87	  // ingested data (see scripts/ingest-real-data.ts). Lets the Evidence
88	  // Explorer filter without re-parsing the excerpt text.
89	  country?: string;
90	  engineType?: string;
91	  feedbackType?: string;
92	}
93	
94	// ---------- Real ingested datasets (scripts/ingest-real-data.ts output) ----------
95	
96	// A single row from a Feedback_Explorer dataset, trimmed for the Evidence
97	// Explorer table. Not tied to a workflow — these are the raw substrate
98	// signals/requirements get derived from, browsable independent of any one
99	// component's workflow.
100	export interface FeedbackRecord {
101	  id: string;
102	  vehicleCode: string; // "F70" | "G60" | "G70"
103	  country: string;
104	  engineType: string; // "ICE" | "BEVE" | "PHEV"
105	  feedbackType: string | null; // "Likes" | "Wants" | "Difficult to Use" | "Defect" | null
106	  text: string;
107	  vfcLevel2: string | null;
108	  vfcLevel3: string | null;
109	  component: ComponentKey | "general";
110	}
111	
112	export interface SalesVolume {
113	  vehicleCode: string;
114	  market: string;
115	  marketCode: string;
