1	// In-memory data store for the hackathon v0.
2	// Swap-out point for Role A: replace this module's internals with a real
3	// DB (Postgres/Prisma or SQLite) while keeping the exported function
4	// signatures identical so nothing above this layer has to change.
5	//
6	// Survives Next.js dev-mode hot reload by hanging off globalThis.
7	
8	import { nanoid } from "nanoid";
9	import type {
10	  Vehicle,
11	  VehicleComponent,
12	  Workflow,
13	  Requirement,
14	  Signal,
15	  SourceRecord,
16	  Stakeholder,
17	  StakeholderReview,
18	  AuditLogEntry,
19	  AISummary,
20	  Actor,
21	  AuditAction,
22	} from "./types";
23	import { buildSeed } from "./seed";
24	
25	interface Store {
26	  vehicles: Vehicle[];
27	  components: VehicleComponent[];
28	  workflows: Workflow[];
29	  requirements: Requirement[];
30	  signals: Signal[];
31	  sources: SourceRecord[];
32	  stakeholders: Stakeholder[];
33	  reviews: StakeholderReview[];
34	  auditLog: AuditLogEntry[];
35	  aiSummaries: AISummary[];
36	}
37	
38	const globalForStore = globalThis as unknown as { __ehlStore?: Store };
39	
40	function freshStore(): Store {
41	  return buildSeed();
42	}
43	
44	export const store: Store = globalForStore.__ehlStore ?? (globalForStore.__ehlStore = freshStore());
45	
46	// ---------- append-only audit log ----------
47	
48	export function logAction(entry: {
49	  workflowId: string;
50	  actor: Actor;
51	  action: AuditAction;
52	  targetType: AuditLogEntry["targetType"];
53	  targetId: string;
54	  oldValue: unknown;
55	  newValue: unknown;
56	  rationale: string;
57	}): AuditLogEntry {
58	  const full: AuditLogEntry = {
59	    id: `log_${nanoid(8)}`,
60	    timestamp: new Date().toISOString(),
61	    ...entry,
62	  };
63	  store.auditLog.push(full);
64	  return full;
65	}
66	
67	export function getAuditLog(workflowId: string): AuditLogEntry[] {
68	  return store.auditLog
69	    .filter((l) => l.workflowId === workflowId)
70	    .sort((a, b) => a.timestamp.localeCompare(b.timestamp));
71	}
72	
73	// ---------- vehicles / components ----------
74	
75	export function listVehicles(): Vehicle[] {
76	  return store.vehicles;
77	}
78	
79	export function getVehicle(id: string): Vehicle | undefined {
80	  return store.vehicles.find((v) => v.id === id);
81	}
82	
83	export function listComponents(vehicleId: string): VehicleComponent[] {
84	  return store.components.filter((c) => c.vehicleId === vehicleId);
85	}
86	
87	export function getComponent(componentId: string): VehicleComponent | undefined {
88	  return store.components.find((c) => c.id === componentId);
89	}
90	
91	// ---------- workflows ----------
92	
93	export function getWorkflow(workflowId: string): Workflow | undefined {
94	  return store.workflows.find((w) => w.id === workflowId);
95	}
96	
97	export function getWorkflowByComponent(componentId: string): Workflow | undefined {
98	  const comp = getComponent(componentId);
99	  if (!comp?.workflowId) return undefined;
100	  return getWorkflow(comp.workflowId);
101	}
102	
103	export function createWorkflow(componentId: string, market: string): Workflow {
104	  const comp = getComponent(componentId);
105	  if (!comp) throw new Error("component not found");
106	  const now = new Date().toISOString();
107	  const workflow: Workflow = {
108	    id: `wf_${nanoid(8)}`,
109	    vehicleId: comp.vehicleId,
110	    componentId,
111	    market,
112	    status: "draft",
113	    stages: [
114	      { key: "ingest", label: "Ingest datasets", status: "active", startedAt: now, completedAt: null, owner: "pm" },
115	      { key: "enrich", label: "Enrich with web knowledge", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
116	      { key: "extract", label: "Extract signals", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
117	      { key: "derive", label: "Derive requirements", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
118	      { key: "score", label: "Score & prioritize", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
119	      { key: "stakeholder_review", label: "Stakeholder review", status: "pending", startedAt: null, completedAt: null, owner: "stakeholder" },
120	      { key: "pm_decision", label: "PM decision", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
121	      { key: "deploy", label: "Move to deploy", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
122	    ],
123	    createdAt: now,
124	    updatedAt: now,
125	  };
126	  store.workflows.push(workflow);
127	  comp.workflowId = workflow.id;
128	
129	  logAction({
130	    workflowId: workflow.id,
131	    actor: { type: "pm", id: "pm_demo", name: "Product Manager" },
132	    action: "workflow_created",
133	    targetType: "workflow",
134	    targetId: workflow.id,
135	    oldValue: null,
136	    newValue: { componentId, market },
137	    rationale: `Started a new requirements workflow for ${comp.label} in ${market}.`,
138	  });
139	
140	  return workflow;
141	}
142	
143	export function updateStage(
144	  workflowId: string,
145	  stageKey: Workflow["stages"][number]["key"],
146	  status: Workflow["stages"][number]["status"],
147	  actor: Actor,
148	) {
149	  const wf = getWorkflow(workflowId);
150	  if (!wf) throw new Error("workflow not found");
151	  const stage = wf.stages.find((s) => s.key === stageKey);
152	  if (!stage) throw new Error("stage not found");
153	  const oldStatus = stage.status;
154	  stage.status = status;
155	  const now = new Date().toISOString();
156	  if (status === "active" && !stage.startedAt) stage.startedAt = now;
157	  if (status === "complete") stage.completedAt = now;
158	  wf.updatedAt = now;
159	
160	  logAction({
161	    workflowId,
162	    actor,
163	    action: "stage_transition",
164	    targetType: "stage",
165	    targetId: stageKey,
166	    oldValue: oldStatus,
167	    newValue: status,
168	    rationale: `${stage.label}: ${oldStatus} -> ${status}`,
169	  });
170	}
171	
172	// ---------- requirements ----------
173	
174	export function listRequirements(workflowId: string): Requirement[] {
175	  return store.requirements
176	    .filter((r) => r.workflowId === workflowId)
177	    .sort((a, b) => b.score - a.score);
178	}
179	
180	export function getRequirement(id: string): Requirement | undefined {
181	  return store.requirements.find((r) => r.id === id);
182	}
183	
184	export function recomputeScore(req: Requirement): number {
185	  const totalWeight = req.scoreFactors.reduce((s, f) => s + f.weight, 0) || 1;
186	  const weighted = req.scoreFactors.reduce((s, f) => s + (f.rawValue * f.weight), 0);
187	  return Math.round((weighted / totalWeight) * 10) / 10;
188	}
189	
190	export function updateRequirementStatus(
191	  id: string,
192	  status: Requirement["status"],
193	  actor: Actor,
194	  rationale: string,
195	): Requirement {
196	  const req = getRequirement(id);
197	  if (!req) throw new Error("requirement not found");
198	  const oldStatus = req.status;
199	  req.status = status;
200	  req.updatedAt = new Date().toISOString();
201	
202	  const actionMap: Record<Requirement["status"], AuditAction> = {
203	    proposed: "requirement_edited",
204	    approved: "requirement_approved",
205	    rejected: "requirement_rejected",
206	    postponed: "requirement_postponed",
207	    challenged: "requirement_challenged",
208	  };
209	
210	  logAction({
211	    workflowId: req.workflowId,
212	    actor,
213	    action: actionMap[status],
214	    targetType: "requirement",
215	    targetId: req.id,
216	    oldValue: oldStatus,
217	    newValue: status,
218	    rationale,
219	  });
220	
221	  return req;
222	}
223	
224	export function updateWeights(
225	  requirementId: string,
226	  weights: Record<string, number>,
227	  actor: Actor,
228	): Requirement {
229	  const req = getRequirement(requirementId);
230	  if (!req) throw new Error("requirement not found");
231	  const oldScore = req.score;
232	  req.scoreFactors = req.scoreFactors.map((f) => ({
233	    ...f,
234	    weight: weights[f.key] ?? f.weight,
235	  }));
236	  req.score = recomputeScore(req);
237	  req.updatedAt = new Date().toISOString();
238	
239	  logAction({
240	    workflowId: req.workflowId,
241	    actor,
242	    action: "weights_adjusted",
243	    targetType: "requirement",
244	    targetId: req.id,
245	    oldValue: { score: oldScore },
246	    newValue: { score: req.score, weights },
247	    rationale: "PM adjusted scoring factor weights.",
248	  });
249	
250	  return req;
251	}
252	
253	// ---------- signals / sources ----------
254	
255	export function listSignals(workflowId: string): Signal[] {
256	  return store.signals.filter((s) => s.workflowId === workflowId);
257	}
258	
259	export function listSources(workflowId: string): SourceRecord[] {
260	  return store.sources.filter((s) => s.workflowId === workflowId);
261	}
262	
263	export function getSourcesByIds(ids: string[]): SourceRecord[] {
264	  return store.sources.filter((s) => ids.includes(s.id));
265	}
266	
267	// ---------- stakeholders / reviews ----------
268	
269	export function listStakeholders(): Stakeholder[] {
270	  return store.stakeholders;
271	}
272	
273	export function getStakeholder(id: string): Stakeholder | undefined {
274	  return store.stakeholders.find((s) => s.id === id);
275	}
276	
277	export function listReviews(workflowId: string): StakeholderReview[] {
278	  return store.reviews.filter((r) => r.workflowId === workflowId);
279	}
280	
281	export function submitReview(
282	  reviewId: string,
283	  decision: StakeholderReview["decision"],
284	  expertOpinion: string,
285	): StakeholderReview {
286	  const review = store.reviews.find((r) => r.id === reviewId);
287	  if (!review) throw new Error("review not found");
288	  review.decision = decision;
289	  review.expertOpinion = expertOpinion;
290	  review.submittedAt = new Date().toISOString();
291	
292	  const stakeholder = getStakeholder(review.stakeholderId);
293	
294	  logAction({
295	    workflowId: review.workflowId,
296	    actor: { type: "stakeholder", id: review.stakeholderId, name: stakeholder?.name ?? "Stakeholder" },
297	    action: "stakeholder_review_submitted",
298	    targetType: "review",
299	    targetId: review.id,
300	    oldValue: { decision: "pending" },
301	    newValue: { decision, expertOpinion },
302	    rationale: expertOpinion,
303	  });
304	
305	  return review;
306	}
307	
308	// ---------- AI summaries ----------
309	
310	export function listAISummaries(workflowId: string): AISummary[] {
311	  return store.aiSummaries.filter((s) => s.workflowId === workflowId);
312	}
313	
314	export function addAISummary(summary: Omit<AISummary, "id" | "generatedAt">): AISummary {
315	  const full: AISummary = {
316	    ...summary,
317	    id: `aisum_${nanoid(8)}`,
318	    generatedAt: new Date().toISOString(),
319	  };
320	  store.aiSummaries.push(full);
