1	// Deterministic requirement derivation + scoring from real ingested data.
2	// No AI involved here on purpose — see docs/ROLE_B_AI.md for which of
3	// these factors stay deterministic forever (frequency, sales_relevance,
4	// evidence_strength) vs. which Role B upgrades to an LLM call with cited
5	// sources (competitive_gap, strategic_fit) once real web/competitor data
6	// is available. `effort` is intentionally never computed here — it's a
7	// placeholder until an Engineering stakeholder confirms it via review.
8	
9	import type { ComponentKey, RequirementCategory, ScoreFactor } from "./types";
10	import type { RawSignal } from "./realData";
11	import type { CustomerStudyScore, SalesVolume } from "./types";
12	
13	export type DerivedKind = "pain" | "opportunity" | "preserve";
14	
15	export interface Candidate {
16	  signal: RawSignal;
17	  kind: DerivedKind;
18	  concentration: number; // 0-1, how dominant the driving sentiment is within this theme
19	}
20	
21	export function classifySignal(signal: RawSignal): Candidate {
22	  const { frequency, likes, wants, difficultToUse, defect } = signal;
23	  const negative = difficultToUse + defect;
24	  const shares = [
25	    { kind: "preserve" as const, value: likes / frequency },
26	    { kind: "opportunity" as const, value: wants / frequency },
27	    { kind: "pain" as const, value: negative / frequency },
28	  ];
29	  shares.sort((a, b) => b.value - a.value);
30	  return { signal, kind: shares[0].kind, concentration: shares[0].value };
31	}
32	
33	// Pick up to `max` signals for a component, prioritizing pain points,
34	// then customer-requested gaps, then strengths worth protecting (US-2.2) —
35	// in that order, since the brief asks us to focus on gaps/opportunities
36	// first and "must not lose" second.
37	export function pickCandidates(signals: RawSignal[], max = 4): Candidate[] {
38	  const classified = signals
39	    .map(classifySignal)
40	    .filter((c) => c.signal.frequency >= 3); // below this, not enough evidence to act on
41	  const byKind = (k: DerivedKind) =>
42	    classified.filter((c) => c.kind === k).sort((a, b) => b.signal.frequency - a.signal.frequency);
43	
44	  const pains = byKind("pain");
45	  const opportunities = byKind("opportunity");
46	  const preserves = byKind("preserve");
47	
48	  const picked: Candidate[] = [];
49	  picked.push(...pains.slice(0, 2));
50	  if (opportunities[0]) picked.push(opportunities[0]);
51	  if (preserves[0] && picked.length < max) picked.push(preserves[0]);
52	  return picked.slice(0, max);
53	}
54	
55	const COMPONENT_TO_CATEGORY: Record<ComponentKey, RequirementCategory> = {
56	  battery: "range_charging",
57	  engine: "driving_experience",
58	  steering: "usability",
59	  windows: "comfort",
60	  interior: "comfort",
61	  exterior: "design_quality",
62	};
63	
64	export function categoryFor(component: ComponentKey): RequirementCategory {
65	  return COMPONENT_TO_CATEGORY[component];
66	}
67	
68	export function titleFor(candidate: Candidate): string {
69	  const { signal, kind } = candidate;
70	  if (kind === "pain") return `Reduce friction: ${signal.theme}`;
71	  if (kind === "opportunity") return `Deliver what customers are asking for: ${signal.theme}`;
72	  return `Protect this strength in the next generation: ${signal.theme}`;
73	}
74	
75	export function descriptionFor(candidate: Candidate): string {
76	  const { signal, kind, concentration } = candidate;
77	  const pct = Math.round(concentration * 100);
78	  const countries = Object.entries(signal.countries)
79	    .sort((a, b) => b[1] - a[1])
80	    .slice(0, 3)
81	    .map(([c]) => c)
82	    .join(", ");
83	  const sample = signal.sampleVerbatims[0]?.slice(0, 200) ?? "";
84	  const label =
85	    kind === "pain" ? "flagged as Difficult to Use / Defect" : kind === "opportunity" ? "explicitly requested (Wants)" : "called out as a Like";
86	  return `${signal.frequency} verbatims mention "${signal.theme}" (top markets: ${countries || "n/a"}); ${pct}% ${label}. Representative feedback: "${sample}${sample.length >= 200 ? "…" : ""}"`;
87	}
