1	// Builds the in-memory store's starting state.
2	//
3	// If a teammate has run `npm run ingest` (real BMW data present in
4	// src/data/*.json, gitignored), buildSeed() assembles real workflows for
5	// all three vehicle lines (F70/1 Series, G60/5 Series, G70/7 Series) from
6	// real verbatims, sales volumes and customer-study benchmarks — see
7	// buildRealSeed() below and docs/DATA_SETUP.md.
8	//
9	// Otherwise it falls back to buildMockSeed(): one hand-written "battery"
10	// workflow for the BMW 5 Series, so the app still runs end to end for
11	// anyone who hasn't copied the (confidential, never-committed) datasets
12	// yet.
13	
14	import { nanoid } from "nanoid";
15	import type {
16	  Vehicle,
17	  VehicleComponent,
18	  Workflow,
19	  Requirement,
20	  Signal,
21	  SourceRecord,
22	  Stakeholder,
23	  StakeholderReview,
24	  AuditLogEntry,
25	  AISummary,
26	  ComponentKey,
27	} from "./types";
28	import {
29	  hasRealData,
30	  loadFeedback,
31	  loadSignals,
32	  loadSales,
33	  loadCustomerStudy,
34	  type RawSignal,
35	} from "./realData";
36	import { pickCandidates, titleFor, descriptionFor, assumptionsFor, evidenceLevelFor, categoryFor, buildScoreFactors, type Candidate } from "./deriveRequirements";
37	
38	export function buildSeed() {
39	  return hasRealData() ? buildRealSeed() : buildMockSeed();
40	}
41	
42	// ===========================================================================
43	// REAL DATA SEED
44	// ===========================================================================
45	
46	const COMPONENT_KEYS: ComponentKey[] = ["battery", "exterior", "interior", "windows", "steering", "engine"];
47	const COMPONENT_LABEL: Record<ComponentKey, string> = {
48	  battery: "Battery & Charging",
49	  exterior: "Exterior & Design",
50	  interior: "Interior & Cabin",
51	  windows: "Windows & Glass",
52	  steering: "Steering & Cockpit",
53	  engine: "Powertrain",
54	};
55	const HOTSPOT: Record<ComponentKey, { xPct: number; yPct: number }> = {
56	  battery: { xPct: 49, yPct: 61 },
57	  exterior: { xPct: 50, yPct: 76 },
58	  interior: { xPct: 61, yPct: 46 },
59	  windows: { xPct: 76, yPct: 38 },
60	  steering: { xPct: 58, yPct: 50 },
61	  engine: { xPct: 24, yPct: 59 },
62	};
63	const VEHICLE_META: Record<string, { name: string; generation: string }> = {
64	  F70: { name: "BMW 1 Series", generation: "F70 → successor" },
65	  G60: { name: "BMW 5 Series", generation: "G60/G68 → successor" },
