261	function toAppSignal(raw: RawSignal, workflowId: string, vehicleCode: string, component: ComponentKey): Signal {
262	  const total = raw.frequency;
263	  const sentiment: Signal["sentiment"] =
264	    raw.likes / total > 0.5 ? "positive" : (raw.difficultToUse + raw.defect) / total > 0.4 ? "negative" : raw.wants / total > 0.3 ? "mixed" : "neutral";
265	  return {
266	    id: signalIdFor(raw, vehicleCode, component),
267	    workflowId,
268	    theme: raw.theme,
269	    frequency: raw.frequency,
270	    sentiment,
271	    sampleVerbatims: raw.sampleVerbatims.slice(0, 4),
272	    sourceIds: raw.feedbackIds.slice(0, 8).map((id) => `src_${id}`),
273	    contradicts: [],
274	  };
275	}
276	
277	function signalIdFor(raw: RawSignal, vehicleCode: string, component: ComponentKey): string {
278	  const slug = raw.theme.toLowerCase().replace(/[^a-z0-9]+/g, "_").slice(0, 40);
279	  return `sig_${vehicleCode.toLowerCase()}_${component}_${slug}`;
280	}
