282	function weightedScore(factors: { weight: number; rawValue: number }[]): number {
283	  const totalWeight = factors.reduce((s, f) => s + f.weight, 0) || 1;
284	  const weighted = factors.reduce((s, f) => s + f.rawValue * f.weight, 0);
285	  return Math.round((weighted / totalWeight) * 10) / 10;
286	}
