441	    { id: "aisum_decision_trail", workflowId: MOCK_WORKFLOW_ID, type: "decision_trail", content: "This is placeholder mock data. Copy the real datasets into data-raw/ and run `npm run ingest` to replace this with a real, data-grounded demo (see docs/DATA_SETUP.md).", basedOnLogIds: [], generatedAt: daysAgo(1) },
442	  ];
443	
444	  return { vehicles, components, workflows: [workflow], requirements: [reqCharging], signals, sources, stakeholders, reviews, auditLog, aiSummaries };
445	}
