1	"use client";
2	
3	import { useEffect, useState, useCallback } from "react";
4	import Link from "next/link";
5	import { useParams } from "next/navigation";
6	import { api } from "@/lib/api-client";
7	import type {
8	  Workflow,
9	  Requirement,
10	  AuditLogEntry,
11	  AISummary,
12	  StakeholderReview,
13	  Stakeholder,
14	  Signal,
15	  SourceRecord,
16	  VehicleComponent,
17	  Vehicle,
18	} from "@/lib/types";
19	import { PipelineStrip } from "@/components/PipelineStrip";
20	import { RequirementCard } from "@/components/RequirementCard";
21	import { AuditLogPanel } from "@/components/AuditLogPanel";
22	import { ReviewerRow } from "@/components/ReviewerRow";
23	import { EvidenceBadge } from "@/components/EvidenceBadge";
24	
25	const SENTIMENT_DOT: Record<Signal["sentiment"], string> = {
26	  positive: "bg-emerald-500",
27	  negative: "bg-red-500",
28	  mixed: "bg-sky-500",
29	  neutral: "bg-neutral-600",
30	};
31	
32	export default function WorkflowPage() {
33	  const params = useParams<{ componentId: string }>();
34	  const [workflow, setWorkflow] = useState<Workflow | null>(null);
35	  const [component, setComponent] = useState<VehicleComponent | null>(null);
36	  const [vehicle, setVehicle] = useState<Vehicle | null>(null);
37	  const [requirements, setRequirements] = useState<Requirement[]>([]);
38	  const [auditLog, setAuditLog] = useState<AuditLogEntry[]>([]);
39	  const [aiSummaries, setAISummaries] = useState<AISummary[]>([]);
40	  const [reviews, setReviews] = useState<StakeholderReview[]>([]);
41	  const [stakeholders, setStakeholders] = useState<Stakeholder[]>([]);
42	  const [signals, setSignals] = useState<Signal[]>([]);
43	  const [sources, setSources] = useState<SourceRecord[]>([]);
44	  const [selectedReqId, setSelectedReqId] = useState<string | null>(null);
45	  const [notFound, setNotFound] = useState(false);
46	
47	  const refresh = useCallback(async () => {
48	    const [comp, wf] = await Promise.all([api.getComponent(params.componentId), api.getWorkflowByComponent(params.componentId)]);
49	    setComponent(comp);
50	    if (!wf) {
51	      setNotFound(true);
52	      return;
53	    }
54	    setWorkflow(wf);
55	    const [reqs, log, summaries, revs, shs, sig, veh] = await Promise.all([
56	      api.listRequirements(wf.id),
57	      api.getAuditLog(wf.id),
58	      api.getAISummaries(wf.id),
59	      api.listReviews(wf.id),
60	      api.listStakeholders(),
61	      api.getSignals(wf.id),
62	      api.getVehicle(wf.vehicleId),
63	    ]);
64	    setRequirements(reqs);
65	    setAuditLog(log);
66	    setAISummaries(summaries);
67	    setReviews(revs);
68	    setStakeholders(shs);
69	    setSignals([...sig.signals].sort((a, b) => b.frequency - a.frequency));
70	    setSources(sig.sources);
71	    setVehicle(veh);
72	  }, [params.componentId]);
73	
74	  useEffect(() => {
75	    refresh();
76	  }, [refresh]);
77	
78	  function onRequirementChanged(updated: Requirement) {
79	    setRequirements((rs) => rs.map((r) => (r.id === updated.id ? updated : r)));
80	    refresh(); // pick up new audit log / summary entries
81	  }
82	
83	  if (notFound) {
84	    return (
85	      <main className="mx-auto max-w-2xl px-6 py-16 text-center">
86	        <p className="text-neutral-400">No workflow exists for this component yet.</p>
87	        <Link href="/" className="mt-4 inline-block text-sm text-sky-400 hover:text-sky-300">
88	          ← Back to landing page
89	        </Link>
90	      </main>
91	    );
92	  }
93	
94	  if (!workflow) {
95	    return <main className="px-6 py-16 text-center text-neutral-500">Loading…</main>;
96	  }
97	
98	  const decisionTrail = aiSummaries.find((s) => s.type === "decision_trail");
99	  const stakeholderOverview = aiSummaries.find((s) => s.type === "stakeholder_overview");
100	  const limitations = aiSummaries.find((s) => s.type === "limitations");
101	
102	  const selectedReq =
103	    requirements.find((r) => r.id === selectedReqId) ??
104	    requirements.find((r) => reviews.some((rv) => rv.requirementId === r.id)) ??
105	    requirements[0] ??
106	    null;
107	  const selectedReviews = selectedReq ? reviews.filter((r) => r.requirementId === selectedReq.id) : [];
108	  const totalMentions = signals.reduce((a, s) => a + s.frequency, 0);
109	
110	  return (
111	    <main className="mx-auto min-h-screen max-w-7xl px-6 py-8">
112	      <div className="mb-6 flex items-start justify-between">
113	        <div>
114	          <Link href="/" className="text-xs text-neutral-500 hover:text-neutral-300">← All components</Link>
115	          <h1 className="mt-1 text-xl font-bold text-neutral-50">
116	            {vehicle?.name ?? "…"} · {component?.label ?? "…"}
117	          </h1>
118	          <p className="font-mono text-xs text-neutral-500">
119	            market={workflow.market} · status={workflow.status} · {totalMentions.toLocaleString()} verbatims across {signals.length} themes
120	          </p>
121	        </div>
122	        <Link
123	          href={`/evidence?vehicleCode=${vehicle?.id?.replace("veh_", "").toUpperCase()}&component=${component?.key}`}
124	          className="shrink-0 border border-neutral-700 px-2.5 py-1.5 text-xs text-neutral-400 hover:border-neutral-500 hover:text-neutral-200"
125	        >
126	          Open Evidence Explorer →
127	        </Link>
128	      </div>
129	
130	      <section className="mb-6 border border-neutral-800 bg-neutral-900/40 p-4">
131	        <PipelineStrip stages={workflow.stages} />
132	      </section>
133	
134	      <div className="grid grid-cols-1 gap-5 lg:grid-cols-[1fr_340px]">
135	        <div className="min-w-0 space-y-5">
136	          {decisionTrail && (
137	            <section className="border-l-2 border-sky-600 bg-sky-950/20 p-3">
138	              <h2 className="text-[10px] font-semibold uppercase tracking-wide text-sky-400">AI summary · decision trail</h2>
139	              <p className="mt-1.5 text-xs leading-relaxed text-neutral-300">{decisionTrail.content}</p>
140	            </section>
141	          )}
142	
143	          <section>
144	            <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
145	              Requirements ({requirements.length})
146	            </h2>
147	            <div className="space-y-3">
148	              {requirements.map((req) => (
149	                <div key={req.id} onClick={() => setSelectedReqId(req.id)}>
150	                  <RequirementCard requirement={req} onChanged={onRequirementChanged} />
151	                </div>
152	              ))}
153	              {requirements.length === 0 && (
154	                <p className="text-sm text-neutral-500">No requirements derived yet.</p>
155	              )}
156	            </div>
157	          </section>
158	
159	          {selectedReq && (
160	            <section className="border border-neutral-800 bg-neutral-900/40 p-3">
161	              <div className="mb-2 flex items-center justify-between">
162	                <h2 className="text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
163	                  Stakeholder reviews — {selectedReq.title}
164	                </h2>
165	                <EvidenceBadge level={selectedReq.evidenceLevel} />
166	              </div>
167	              {stakeholderOverview && (
168	                <p className="mb-2 border-l-2 border-violet-600 bg-violet-950/20 p-2 text-[11px] text-violet-200">
169	                  <span className="font-semibold">AI overview: </span>
170	                  {stakeholderOverview.content}
171	                </p>
172	              )}
173	              <div className="space-y-2">
174	                {selectedReviews.map((rev) => (
175	                  <ReviewerRow key={rev.id} review={rev} stakeholder={stakeholders.find((s) => s.id === rev.stakeholderId)} />
176	                ))}
177	                {selectedReviews.length === 0 && (
178	                  <p className="text-xs text-neutral-500">No reviews requested for this requirement yet.</p>
179	                )}
