cat > /tmp/shots/capture.mjs <<'EOF'
import { chromium } from "playwright-core";
import { mkdirSync } from "fs";
const OUT = "/tmp/shots/new"; mkdirSync(OUT, { recursive: true });
const base = "http://localhost:3100";
const b = await chromium.launch({ channel: "chrome", headless: true });
const p = await b.newPage({ viewport: { width: 800, height: 621 }, deviceScaleFactor: 2 });

// scrollTo: number, or a text whose element top should land at `at` px in the viewport
const shots = [
  { file: "01-landing.jpg", url: "/", settle: 9000 },
  { file: "02-workflow-nav.jpg", url: "/workflow/comp_g60_battery" },
  { file: "03-workflow-decision-trail.jpg", url: "/workflow/comp_g60_battery", text: "Kompass summary · decision trail", at: 300 },
  { file: "04-workflow-requirement.jpg", url: "/workflow/comp_g60_battery", text: "Ranked by weighted score", at: 158 },
  { file: "05-stakeholder.jpg", url: "/stakeholder/wf_g60_battery/sh_controlling" },
  { file: "06-evidence-hero.jpg", url: "/evidence" },
  { file: "07-evidence-filters.jpg", url: "/evidence?market=Europe", text: "Component", exact: true, at: 150 },
];

for (const s of shots) {
  await p.goto(base + s.url, { waitUntil: "networkidle", timeout: 120000 }).catch(e => console.log("nav", s.file, e.message));
  await p.waitForTimeout(s.settle ?? 3000);
  if (s.text) {
    const y = await p.evaluate(({ text, exact }) => {
      const els = [...document.querySelectorAll("body *")].filter(e => e.children.length === 0 || e.childElementCount < 3);
      const el = els.find(e => { const t = e.textContent.replace(/\s+/g, " ").trim(); return exact ? t === text : t.includes(text); });
      return el ? el.getBoundingClientRect().top + window.scrollY : null;
    }, { text: s.text, exact: !!s.exact });
    if (y == null) console.log("NOT FOUND:", s.text);
    else await p.evaluate(top => window.scrollTo(0, top), Math.max(0, y - s.at));
    await p.waitForTimeout(1200);
  }
  await p.screenshot({ path: `${OUT}/${s.file}`, type: "jpeg", quality: 85 });
  console.log("captured", s.file);
}
await b.close();
EOF
cd /tmp/shots && node capture.mjs && ls -la new | awk '{print $5, $9}'

